package com.ChaTop.Backend.Responses;public class RentalResponse {    private int id;    private String name;    private int surface;    private double price;    private String picture;    private String description;    private int owner_id;    public int getOwner_id() {        return owner_id;    }    public void setOwner_id(int owner_id) {        this.owner_id = owner_id;    }    private UserResponse owner;    public int getId() {        return id;    }    public void setId(int id) {        this.id = id;    }    public String getName() {        return name;    }    public void setName(String name) {        this.name = name;    }    public int getSurface() {        return surface;    }    public void setSurface(int surface) {        this.surface = surface;    }    public double getPrice() {        return price;    }    public void setPrice(double price) {        this.price = price;    }    public String getPicture() {        return picture;    }    public void setPicture(String picture) {        this.picture = picture;    }    public String getDescription() {        return description;    }    public void setDescription(String description) {        this.description = description;    }    public UserResponse getOwner() {        return owner;    }    public void setOwner(UserResponse owner) {        this.owner = owner;    }}